  const valid = Object.fromEntries(q.vars.map((v, j) => { const vals = R.fits[S.saveIdx].b.groups.flatMap(g => q.kind === 'linear' ? [] : g.x.map(xx => xx[j])); return [v, vals.length ? [Math.min(...vals), Math.max(...vals)] : null]; }).filter(e => e[1]));
